<article class="dashboard-enter bg-white rounded-xl border border-slate-200 shadow-sm min-w-0 overflow-hidden">
    <div class="flex flex-wrap items-center justify-between gap-2 p-3"><div><h2 class="text-sm font-bold text-slate-900"><?= $own?'My recent orders':'Recent orders' ?></h2><p class="text-[10px] text-slate-500 mt-0.5">Latest <?= count($sales['orders']) ?> orders in the selected period · totals after returns</p></div><div class="flex flex-wrap gap-1" aria-label="Filter recent orders"><?php foreach (['all'=>'All orders','due'=>'Payment due','returned'=>'Returned'] as $key=>$label): ?><button type="button" data-dashboard-filter="<?= $key ?>" aria-pressed="<?= $key==='all'?'true':'false' ?>" class="border border-slate-200 rounded-md px-2 py-1 text-[10px] text-slate-500"><?= $label ?></button><?php endforeach; ?></div><label class="sr-only" for="dashboardOrderSearch">Search recent orders</label><input id="dashboardOrderSearch" type="search" maxlength="120" placeholder="Search orders…" class="w-36 border border-slate-200 rounded-md px-2 py-1.5 text-xs"></div>
    <div class="overflow-x-auto"><table class="w-full text-left text-xs"><thead class="bg-brand-50 text-[10px] text-slate-500"><tr><th class="px-3 py-2">Date / time</th><th class="px-3 py-2">Order</th><th class="px-3 py-2">Customer</th><th class="px-3 py-2 text-right">Net total</th><th class="px-3 py-2 text-right">Settled</th><th class="px-3 py-2 text-right">Due</th><th class="px-3 py-2">Status</th><th class="px-3 py-2">View</th></tr></thead><tbody class="divide-y divide-slate-100">
    <?php foreach ($sales['orders'] as $order): ?><tr data-dashboard-order data-due="<?= $order['due']>0?'1':'0' ?>" data-returned="<?= $order['returned']>0?'1':'0' ?>" class="hover:bg-slate-50"><td class="px-3 py-2 whitespace-nowrap text-slate-500"><?= esc(substr($order['date'],0,16)) ?></td><td class="px-3 py-2 font-mono text-[10px]"><?= esc($order['reference']) ?></td><td class="px-3 py-2"><?= esc($order['customer']) ?></td><td class="px-3 py-2 text-right tabular-nums">$<?= number_format($order['total'],2) ?><?php if ($order['returned']>0): ?><span class="block text-[9px] text-amber-700">Returned $<?= number_format($order['returned'],2) ?></span><?php endif; ?></td><td class="px-3 py-2 text-right tabular-nums">$<?= number_format($order['paid'],2) ?></td><td class="px-3 py-2 text-right tabular-nums <?= $order['due']>0?'text-rose-600':'' ?>">$<?= number_format($order['due'],2) ?></td><td class="px-3 py-2"><span class="rounded-md px-1.5 py-0.5 text-[10px] font-semibold <?= $order['status']==='Paid'?'bg-emerald-50 text-emerald-700':($order['status']==='Partial'?'bg-amber-50 text-amber-700':'bg-rose-50 text-rose-700') ?>"><?= esc($order['status']) ?></span></td><td class="px-3 py-2"><button type="button" data-dashboard-view="<?= $order['id'] ?>" aria-label="View order <?= esc($order['reference'],'attr') ?>" class="text-brand-600 p-1.5 hover:bg-brand-50 rounded-md"><i data-lucide="eye" class="w-3.5 h-3.5" aria-hidden="true"></i></button></td></tr><?php endforeach; ?>
    <tr id="dashboardNoOrders" <?= $sales['orders']?'hidden':'' ?>><td colspan="8" class="p-6 text-center text-slate-400">No matching orders.</td></tr>
    </tbody></table></div>
</article>
